const std = @import("std");

pub fn main() !void {
    const limit: usize = 50;
    var is_prime = [_]bool{true} ** (limit + 1);
    is_prime[0] = false;
    is_prime[1] = false;

    var i: usize = 2;
    while (i * i <= limit) {
        if (is_prime[i]) {
            var j = i * i;
            while (j <= limit) {
                is_prime[j] = false;
                j += i;
            }
        }
        i += 1;
    }

    for (2..limit + 1) |n| {
        if (is_prime[n]) std.debug.print("{} ", .{n});
    }
    std.debug.print("\n", .{});
}
